//! Tiny media generated by the real ffmpeg, one directory per test so tests run in parallel.

use std::path::{Path, PathBuf};
use std::thread;
use std::time::{Duration, Instant};

use crate::ffmpeg::Ffmpeg;

pub struct TestMedia {
    dir: PathBuf,
}

impl TestMedia {
    pub fn new(test: &str) -> Self {
        let name = format!("ffmpeditor-media-{}-{test}", std::process::id());
        let dir = std::env::temp_dir().join(name);
        std::fs::create_dir_all(&dir).unwrap();
        Self { dir }
    }

    /// 3 s of 320x240 @ 30 fps with a keyframe every second, plus a sine tone.
    pub fn video_with_audio(&self) -> PathBuf {
        self.generate(
            "video_with_audio.mp4",
            &[
                "-f",
                "lavfi",
                "-i",
                "testsrc2=size=320x240:rate=30:duration=3",
                "-f",
                "lavfi",
                "-i",
                "sine=frequency=440:duration=3",
                "-c:v",
                "libx264",
                "-preset",
                "ultrafast",
                "-g",
                "30",
                "-c:a",
                "aac",
                "-shortest",
            ],
        )
    }

    /// 2 s of 320x240 @ 30 fps.
    pub fn video_only(&self) -> PathBuf {
        self.generate(
            "video_only.mp4",
            &[
                "-f",
                "lavfi",
                "-i",
                "testsrc2=size=320x240:rate=30:duration=2",
                "-c:v",
                "libx264",
                "-preset",
                "ultrafast",
                "-g",
                "30",
            ],
        )
    }

    /// 2 s sine tone.
    pub fn audio_only(&self) -> PathBuf {
        self.generate(
            "audio_only.wav",
            &["-f", "lavfi", "-i", "sine=frequency=440:duration=2"],
        )
    }

    pub fn missing(&self) -> PathBuf {
        self.dir.join("missing.mp4")
    }

    fn generate(&self, name: &str, args: &[&str]) -> PathBuf {
        let path = self.dir.join(name);
        let status = ffmpeg()
            .ffmpeg()
            .args(["-v", "error", "-y"])
            .args(args)
            .arg(&path)
            .status()
            .unwrap();
        assert!(status.success(), "generating {name}");
        path
    }
}

impl Drop for TestMedia {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

pub fn ffmpeg() -> Ffmpeg {
    Ffmpeg::new(Path::new("ffmpeg"))
}

pub fn wait_until(mut done: impl FnMut() -> bool) {
    let deadline = Instant::now() + Duration::from_secs(30);
    while !done() {
        assert!(Instant::now() < deadline, "timed out");
        thread::sleep(Duration::from_millis(10));
    }
}
